findings.codeql_raw_query:
/**
 * @name Insecure eval/exec usage in attrs (path)
 * @description Track remote/user-controlled data reaching eval/exec in attrs.
 * @kind path-problem
 * @problem.severity error
 * @id py/attrs-eval-exec-taint
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module EvalExecTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module EvalExecTaintFlow = TaintTracking::Global<EvalExecTaintConfig>;
import EvalExecTaintFlow::PathGraph

from EvalExecTaintFlow::PathNode source, EvalExecTaintFlow::PathNode sink
where EvalExecTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches eval/exec here.", source.getNode(), "user input"
